Una biblioteca quiere ver, por estantería, los títulos que hay en ella.

function librosPorEstanteria(libros) {
  const porEstanteria = {};
  for (const libro of libros) {
    if (!(libro.estanteria in porEstanteria)) {
      porEstanteria[libro.estanteria] = [];
    }
    porEstanteria[libro.estanteria].push(libro.titulo);
  }
  return porEstanteria;
}
